# Dựng shared/landscape.css từ scripts/cozygame/landscape.src.css: bọc trong 2 điều kiện màn ngang (điện thoại thấp; máy tính bảng cảm ứng). Chạy: python3 scripts/cozygame/mklandscape.py
import os
d=os.path.dirname(os.path.abspath(__file__));src=open(os.path.join(d,"landscape.src.css"),encoding="utf-8").read()
head=src.split("*/",1)[0]+"*/\n";body=src.split("*/",1)[1]
pre="#home>.hl,#home>.hr{display:contents}\n/* màn rất hẹp (mọi hướng): thu nhỏ nút thanh trên để tiêu đề game không bị cắt “…” */\n#play.tight .top>.ib{width:32px;height:32px;min-width:32px;min-height:32px;font-size:3.2cqw}\n/* màn dọc: tên game được chuyển xuống ngay trên khối nội dung ở giữa màn chọn (bản sao #homeTitle do landscape.js dựng); thanh trên chỉ còn các nút */\n.hometitle{display:none}\n@media (orientation:portrait){#play[data-scr=\"home\"] .hometitle{display:block;margin:0;text-align:center;white-space:normal;text-wrap:balance;overflow-wrap:anywhere;font:400 7.4cqw/1.15 var(--display);color:var(--accent);letter-spacing:.01em}#play[data-scr=\"home\"] .top>h1{visibility:hidden}}\n/* màn dọc: tên game khi đang chơi nằm ngay trên cụm điểm + khung chơi (bản sao #gameTitle do landscape.js dựng) */\n.gametitle{display:none}\n@media (orientation:portrait){#play[data-scr=\"game\"] .gametitle{display:block;flex:none;margin:0;text-align:center;white-space:normal;text-wrap:balance;overflow-wrap:anywhere;font:400 5.6cqw/1.15 var(--display);color:var(--accent)}#play[data-scr=\"game\"] .top>h1{visibility:hidden}}\n/* màn dọc, khung chơi vuông/ít cao: gom bảng điểm + khung chơi + nút hành động thành một cụm ở giữa màn hình thay vì dính mép trên/dưới (--ar = cao/rộng của canvas, do landscape.js đặt) */\n@media (orientation:portrait){#play #game{justify-content:center;gap:3cqw}#play #cvw{flex:0 1 calc(92cqw*var(--ar,1.1));min-height:0}}\n"
out=head+pre+"@media (orientation:landscape) and (max-height:700px) and (min-width:560px),(orientation:landscape) and (pointer:coarse) and (max-height:900px) and (min-width:800px){\n"+body.strip()+"\n}\n"
open(os.path.join(d,"..","..","shared","landscape.css"),"w",encoding="utf-8").write(out);print("ok",len(out))
